const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver'
};
return [{ json: cfg }];

const tls = require('tls');
const host = $('Konfiguration').first().json.publicHost;
const result = await new Promise((resolve) => {
  const socket = tls.connect({ host, port: 443, servername: host, timeout: 10000 }, () => {
    const cert = socket.getPeerCertificate();
    socket.end();
    resolve({ ok: true, days: Math.floor((new Date(cert.valid_to).getTime() - Date.now()) / 86400000) });
  });
  socket.on('error', (e) => resolve({ ok: false, error: e.message }));
  socket.on('timeout', () => {
    socket.destroy();
    resolve({ ok: false, error: 'Zeitueberschreitung' });
  });
});
return [{ json: result }];

const cfg = $('Konfiguration').first().json;
const reachable = (name, label) => {
  const res = $(name).first().json;
  const status = res.statusCode;
  const ok = typeof status === 'number' && status >= 200 && status < 500 && status !== 404;
  return { name: label, ok, detail: ok ? '' : label + ' von aussen nicht erreichbar (HTTP ' + (status || res.error || 'keine Antwort') + ')' };
};
const checks = [
  reachable('SCEP oeffentlich', 'SCEP'),
  reachable('Enrollment-Profil oeffentlich', 'Enrollment-Profil'),
  reachable('MDM-Endpunkt oeffentlich', 'MDM-Endpunkt')
];
const tlsResult = $('TLS pruefen').first().json;
checks.push({ name: 'TLS', ok: tlsResult.ok && tlsResult.days >= 14, detail: tlsResult.ok ? 'TLS-Zertifikat von ' + cfg.publicHost + ' laeuft in ' + tlsResult.days + ' Tagen ab' : 'TLS-Verbindung zu ' + cfg.publicHost + ' fehlgeschlagen: ' + tlsResult.error });
const unavailable = $('Nicht verfuegbare Deployments').first().json.body;
const names = ((unavailable && unavailable.data && unavailable.data.result) || []).map((r) => r.metric.deployment);
const vmReachable = unavailable && unavailable.status === 'success';
checks.push({ name: 'Pods', ok: vmReachable && names.length === 0, detail: vmReachable ? 'Deployments nicht verfuegbar: ' + names.join(', ') : 'Pod-Status nicht abrufbar (VictoriaMetrics)' });
const token = $('DEP-Token vorhanden').first().json;
const syncer = $('Syncer nicht verfuegbar').first().json.body;
const syncerDown = syncer && syncer.data && syncer.data.result && syncer.data.result.length > 0;
checks.push({ name: 'DEP-Syncer', ok: !(token.statusCode === 200 && syncerDown), detail: 'depsyncer laeuft nicht, obwohl ein DEP-Token hinterlegt ist' });
const profiles = $input.first().json;
checks.push({ name: 'Profile', ok: Number(profiles.errors || 0) === 0 && Number(profiles.stale || 0) === 0, detail: Number(profiles.errors || 0) + ' Profil-Installation(en) fehlgeschlagen, ' + Number(profiles.stale || 0) + ' seit ueber 24 Stunden ohne Quittung' });
return [{ json: { checks } }];

const rows = $input.all().map((item) => item.json).filter((row) => row.kind);
const alarms = rows.filter((row) => row.kind === 'alarm');
const recovered = rows.filter((row) => row.kind === 'ok');
const out = [];
if (alarms.length > 0) out.push({ json: { title: 'MDM: ' + alarms.length + ' Pruefung(en) fehlgeschlagen', message: alarms.map((row) => '- ' + row.detail).join('\n') + '\n\nFehlersuche: Doku Betrieb, Abschnitt Troubleshooting.', priority: 'high', tags: 'rotating_light' } });
if (recovered.length > 0) out.push({ json: { title: 'MDM: wieder in Ordnung', message: recovered.map((row) => '- ' + row.check_name + ' (Stoerung seit ' + row.detail + ')').join('\n'), priority: 'default', tags: 'white_check_mark' } });
return out;
